//! Port of `models/mask_builder.py` (the default `AEMask2` mask component) plus the helper
//! `_stamp_next_component_number` of `models/component.py` that every mask entry point uses.
//!
//! The parameter table and binary payloads are `data/mask_template.py`, carried here as
//! [`super::mask_template`] (generated by `tools/make_mask_template.py`). A mask appears in two
//! roles with the same parameters: attached to an effect (a `SubComponents` entry) or applied to
//! the clip (its own chain, referenced from the track item as `SelectionComponents`).

use super::mask_template::{MASK_CLASS_ID, MASK_PARAMS, MASK_VERSION, PRIVATE_DATA, SELECTION_CHAIN};
use super::{leaf, top};
use crate::error::{value, Result};
use crate::xml::mutations::insert_before;
use crate::xml::{NodeId, PremiereDocument, Tree};

/// `MASK_MATCH_NAME`.
pub const MASK_MATCH_NAME: &str = "AE.ADBE AEMask2";

/// `build_mask_params`: register the 27 default mask parameters; returns their ObjectIDs.
///
/// Arbitrary-data payloads are written in full only when the document does not already store
/// their hash (Premiere keeps one copy per `BinaryHash`).
pub fn build_mask_params(document: &mut PremiereDocument) -> Result<Vec<String>> {
    let mut ids = Vec::new();
    for param in MASK_PARAMS {
        let element = top(&mut document.tree, param.tag, param.class_id, param.version, None);
        let mut children = Vec::new();
        for field in param.fields {
            let child = document.tree.sub_element(element, field.tag, field.attrs);
            let binary_hash = field.attrs.iter().find(|(k, _)| *k == "BinaryHash").map(|(_, v)| *v);
            if let Some(text) = field.text {
                let stored = match binary_hash {
                    Some(h) if !h.is_empty() => document.payload_stored(h)?,
                    _ => false,
                };
                if !stored {
                    document.tree.set_text(child, Some(text));
                }
            }
            document.tree.set_tail(child, Some("\n\t\t"));
            children.push(child);
        }
        let Some(&last) = children.last() else { return value("list index out of range") };
        document.tree.set_tail(last, Some("\n\t"));
        ids.push(document.add_object(element)?);
    }
    // New payload carriers may have joined the store.
    document.invalidate_payloads();
    Ok(ids)
}

/// `build_mask_component`: register the mask's `VideoFilterComponent`; returns (ObjectID,
/// element).
///
/// The two roles share the parameter set but not the shell: the clip role carries the
/// `NextComponentNumber` bag, a chain-local `ID` and `Intrinsic`; the effect role an
/// `InstanceName` numbered by position (`01`, `02`, ...).
pub fn build_mask_component(
    document: &mut PremiereDocument,
    param_ids: &[String],
    clip_role: bool,
    instance_name: &str,
) -> Result<(String, NodeId)> {
    let tree = &mut document.tree;
    let element = top(tree, "VideoFilterComponent", MASK_CLASS_ID, MASK_VERSION, None);
    let inner = tree.sub_element(element, "Component", &[("Version", "7")]);
    tree.set_text(inner, Some("\n\t\t\t"));
    tree.set_tail(inner, Some("\n\t\t"));
    if clip_role {
        let node = tree.sub_element(inner, "Node", &[("Version", "1")]);
        tree.set_text(node, Some("\n\t\t\t\t"));
        tree.set_tail(node, Some("\n\t\t\t"));
        let properties = tree.sub_element(node, "Properties", &[("Version", "1")]);
        tree.set_text(properties, Some("\n\t\t\t\t\t"));
        tree.set_tail(properties, Some("\n\t\t\t"));
        let key = tree.sub_element(properties, "BE.VideoFilterComponent.NextComponentNumber", &[]);
        tree.set_text(key, Some("2"));
        tree.set_tail(key, Some("\n\t\t\t\t"));
    }
    let params = tree.sub_element(inner, "Params", &[("Version", "1")]);
    tree.set_text(params, Some("\n\t\t\t\t"));
    tree.set_tail(params, Some("\n\t\t\t"));
    for (index, param_id) in param_ids.iter().enumerate() {
        let i = index.to_string();
        let entry = tree.sub_element(params, "Param", &[("Index", &i), ("ObjectRef", param_id)]);
        tree.set_tail(entry, Some(if index + 1 < param_ids.len() { "\n\t\t\t\t" } else { "\n\t\t\t" }));
    }
    if clip_role {
        leaf(tree, inner, "ID", "1", "\n\t\t\t");
        leaf(tree, inner, "DisplayName", "Mask2", "\n\t\t\t");
        leaf(tree, inner, "Intrinsic", "true", "\n\t\t");
    } else {
        leaf(tree, inner, "DisplayName", "Mask2", "\n\t\t\t");
        leaf(tree, inner, "InstanceName", instance_name, "\n\t\t");
    }
    let private = tree.sub_element(
        element,
        "PremiereFilterPrivateData",
        &[("Encoding", "base64"), ("BinaryHash", PRIVATE_DATA.0)],
    );
    if !document.payload_stored(PRIVATE_DATA.0)? {
        document.tree.set_text(private, Some(format!("{}\n\t\t", PRIVATE_DATA.1)));
    }
    let tree = &mut document.tree;
    tree.set_tail(private, Some("\n\t\t"));
    leaf(tree, element, "MatchName", MASK_MATCH_NAME, "\n\t\t");
    leaf(tree, element, "VideoFilterType", "2", "\n\t");
    let object_id = document.add_object(element)?;
    document.invalidate_payloads();
    Ok((object_id, element))
}

/// `attach_sub_mask`: wire a registered mask into a holder's `SubComponents` list.
///
/// Creates the list ahead of `MatchName` on the first attach and appends with the running index
/// after.
pub fn attach_sub_mask(tree: &mut Tree, holder: NodeId, mask_id: &str) -> Result<()> {
    let subs = match tree.child_by_tag(holder, "SubComponents") {
        None => {
            let subs = tree.new_element_with("SubComponents", &[("Version", "1")]);
            tree.set_text(subs, Some("\n\t\t\t"));
            insert_before(tree, holder, "MatchName", subs)?;
            (subs, 0usize)
        }
        Some(subs) => {
            let entries: Vec<NodeId> =
                tree.children(subs).iter().copied().filter(|&c| tree.tag(c) == "SubComponent").collect();
            let Some(&last) = entries.last() else { return value("list index out of range") };
            tree.set_tail(last, Some("\n\t\t\t"));
            (subs, entries.len())
        }
    };
    let index = subs.1.to_string();
    let entry = tree.sub_element(subs.0, "SubComponent", &[("Index", &index), ("ObjectRef", mask_id)]);
    tree.set_tail(entry, Some("\n\t\t"));
    Ok(())
}

/// `build_selection_chain`: register the clip-role `VideoComponentChain`; returns its ObjectID.
pub fn build_selection_chain(document: &mut PremiereDocument, mask_id: &str) -> Result<String> {
    let tree = &mut document.tree;
    let element = top(tree, SELECTION_CHAIN.0, SELECTION_CHAIN.1, SELECTION_CHAIN.2, None);
    let chain = tree.sub_element(element, "ComponentChain", &[("Version", "3")]);
    tree.set_text(chain, Some("\n\t\t\t"));
    tree.set_tail(chain, Some("\n\t"));
    let components = tree.sub_element(chain, "Components", &[("Version", "1")]);
    tree.set_text(components, Some("\n\t\t\t\t"));
    tree.set_tail(components, Some("\n\t\t"));
    let entry = tree.sub_element(components, "Component", &[("Index", "0"), ("ObjectRef", mask_id)]);
    tree.set_tail(entry, Some("\n\t\t\t"));
    document.add_object(element)
}

/// `component._stamp_next_component_number`: the allocation counter a mask holder carries once
/// numbering starts (absent beside a single effect mask, stamped 2 by the second; the clip
/// role's intrinsic holder starts at 2 and counts on from there). Leads the property bag when
/// one exists. `inner` is the holder's inner `Component` (`None` is an error, as in Python).
pub fn stamp_next_component_number(tree: &mut Tree, inner: Option<NodeId>, number: i64) -> Result<()> {
    let Some(inner) = inner else { return value("component has no inner Component element") };
    if let Some(key) = tree.find1(inner, "Node/Properties/BE.VideoFilterComponent.NextComponentNumber") {
        tree.set_text(key, Some(number.to_string()));
        return Ok(());
    }
    if let Some(properties) = tree.find1(inner, "Node/Properties") {
        let key = tree.new_element("BE.VideoFilterComponent.NextComponentNumber");
        tree.set_text(key, Some(number.to_string()));
        let lead = tree.text(properties).map(str::to_string);
        tree.set_tail(key, lead);
        tree.insert(properties, 0, key);
        return Ok(());
    }
    let node = tree.new_element_with("Node", &[("Version", "1")]);
    tree.set_text(node, Some("\n\t\t\t\t"));
    let lead = tree.text(inner).map(str::to_string);
    tree.set_tail(node, lead);
    let properties = tree.sub_element(node, "Properties", &[("Version", "1")]);
    tree.set_text(properties, Some("\n\t\t\t\t\t"));
    tree.set_tail(properties, Some("\n\t\t\t"));
    let key = tree.sub_element(properties, "BE.VideoFilterComponent.NextComponentNumber", &[]);
    tree.set_text(key, Some(number.to_string()));
    tree.set_tail(key, Some("\n\t\t\t\t"));
    tree.insert(inner, 0, node);
    Ok(())
}
